 useEffect(()=>{let cancelled=false;if(!user)return;setDataReady(false);setAuthStatus('loading-data');api('/api/data').then(async({data})=>{if(cancelled)return;const hasCloudData=Object.keys(data||{}).length>0;if(hasCloudData){setHabits(Object.hasOwn(data,'habits')?data.habits:initialHabits);setLogs(Object.hasOwn(data,'logs')?data.logs:{});setEntries(Object.hasOwn(data,'entries')?data.entries:[]);setWork(Object.hasOwn(data,'work')?data.work:starterWork);setCycles(Object.hasOwn(data,'cycles')?data.cycles:[]);setDsa(Object.hasOwn(data,'dsa')?data.dsa:starterDsa);setExpenses(Object.hasOwn(data,'expenses')?data.expenses:[]);setYearStory(Object.hasOwn(data,'yearstory')?data.yearstory:{});setJournalDays(Object.hasOwn(data,'journaldays')?data.journaldays:{});setImprovement(Object.hasOwn(data,'improvement')?data.improvement:{});setTodoItems(Object.hasOwn(data,'todo')?data.todo:[])}else if(importOnLogin){const local={habits,logs,entries,work,cycles,dsa,expenses,yearstory:yearStory,journaldays:journalDays,improvement,todo:todoItems};for(const [key,value] of Object.entries(local)){await api(`/api/data/${key}`,{method:'PUT',body:JSON.stringify({value})})}}else{setHabits(initialHabits);setLogs({});setEntries([]);setWork(starterWork);setCycles([]);setDsa(starterDsa);setExpenses([]);setYearStory({});setJournalDays({});setImprovement({});setTodoItems([])}if(!cancelled){setDataReady(true);setAuthStatus('signedin')}}).catch(error=>{if(!cancelled){setSyncError(error.message);setUser(null);setAuthStatus('signedout')}});return()=>{cancelled=true}},[user]);
 useEffect(()=>localStorage.setItem('mls-habits',JSON.stringify(habits)),[habits]);
