 useEffect(()=>{if(user&&dataReady)api('/api/data/logs',{method:'PUT',body:JSON.stringify({value:logs})}).catch(e=>setSyncError(e.message))},[user,dataReady,logs]);
 useEffect(()=>{if(user&&dataReady)api('/api/data/entries',{method:'PUT',body:JSON.stringify({value:entries})}).catch(e=>setSyncError(e.message))},[user,dataReady,entries]);
 useEffect(()=>{if(user&&dataReady)api('/api/data/work',{method:'PUT',body:JSON.stringify({value:work})}).catch(e=>setSyncError(e.message))},[user,dataReady,work]);
 useEffect(()=>{if(user&&dataReady)api('/api/data/cycles',{method:'PUT',body:JSON.stringify({value:cycles})}).catch(e=>setSyncError(e.message))},[user,dataReady,cycles]);
 useEffect(()=>{if(user&&dataReady)api('/api/data/dsa',{method:'PUT',body:JSON.stringify({value:dsa})}).catch(e=>setSyncError(e.message))},[user,dataReady,dsa]);
 useEffect(()=>{if(user&&dataReady)api('/api/data/expenses',{method:'PUT',body:JSON.stringify({value:expenses})}).catch(e=>setSyncError(e.message))},[user,dataReady,expenses]);
 useEffect(()=>{if(user&&dataReady)api('/api/data/yearstory',{method:'PUT',body:JSON.stringify({value:yearStory})}).catch(e=>setSyncError(e.message))},[user,dataReady,yearStory]);
 useEffect(()=>{if(user&&dataReady)api('/api/data/journaldays',{method:'PUT',body:JSON.stringify({value:journalDays})}).catch(e=>setSyncError(e.message))},[user,dataReady,journalDays]);
 useEffect(()=>{if(user&&dataReady)api('/api/data/improvement',{method:'PUT',body:JSON.stringify({value:improvement})}).catch(e=>setSyncError(e.message))},[user,dataReady,improvement]);
 useEffect(()=>{if(user&&dataReady)api('/api/data/todo',{method:'PUT',body:JSON.stringify({value:todoItems})}).catch(e=>setSyncError(e.message))},[user,dataReady,todoItems]);
 const days=useMemo(()=>weekDays(week),[week]);
 const todayKey=keyFor(today);
