 const toggleLog=(habitId,dateKey)=>setLogs(p=>({...p,[`${habitId}:${dateKey}`]:!p[`${habitId}:${dateKey}`]}));
 const saveJournal=()=>{
   if(!journalContent.trim()&&!journalTitle.trim()&&!journalPhotos.length)return;
   setEntries(p=>[{id:uid(),date:journalDate,title:journalTitle||'A little note to myself',content:journalContent,mood:journalMood,photos:journalPhotos,createdAt:new Date().toISOString()},...p]);
   setJournalTitle('');setJournalContent('');setJournalPhotos([]);
 };
 const dailyQuestions=['What do I need to give myself more credit for?','What am I holding onto that I can release?','What made me feel most like myself today?','What is one small thing I can do for my future self?','What boundary do I want to honour?','What did I learn about myself today?','What deserves less of my energy?'];
 const dailyTasks=['Delete 10 unwanted photos','Take a two-hour digital detox','Unfollow accounts that no longer inspire you','Organise one drawer or shelf','Spend 20 minutes learning something new','Clear your downloads folder','Write down three things you have been postponing'];
 const dailyIndex=Math.abs([...journalDate].reduce((a,c)=>a+c.charCodeAt(0),0))%dailyQuestions.length;
 const journalCalendarDates=monthDates(journalMonth.getFullYear(),journalMonth.getMonth());
 const dayJournal=journalDays[journalDate]||{gratitude:['','',''],overall:'',darling:'',song:'',questionAnswer:'',taskDone:false};
 const updateDayJournal=(field,value)=>setJournalDays(prev=>({...prev,[journalDate]:{...(prev[journalDate]||{gratitude:['','',''],overall:'',darling:'',song:'',questionAnswer:'',taskDone:false}),[field]:value}}));
 const addImprovementGoal=e=>{e.preventDefault();if(!improvementForm.title.trim())return;setImprovement(prev=>({...prev,[improvementMonth]:[...(prev[improvementMonth]||[]),{...improvementForm,id:uid(),done:false}]}));setImprovementForm({title:'',category:'Career',notes:''})};
 const addTodo=e=>{e.preventDefault();if(!todoForm.title.trim())return;setTodoItems(prev=>[{...todoForm,id:uid(),done:false,createdAt:new Date().toISOString()},...prev]);setTodoForm({title:'',priority:'Medium',dueDate:'',category:'Personal'})};
 const addHabit=e=>{e.preventDefault();if(newHabit.trim()){setHabits(p=>[...p,{id:uid(),name:newHabit.trim(),emoji:'🌸'}]);setNewHabit('');setShowHabitForm(false)}};
 const addWork=e=>{e.preventDefault();if(workForm.title.trim()){setWork(p=>[{...workForm,id:uid(),minutes:Number(workForm.minutes)||0},...p]);setWorkForm({...workForm,title:'',achievement:'',pr:'',follow:'',followDate:''});setShowWorkForm(false)}};
 const addDsa=e=>{e.preventDefault();if(dsaForm.name.trim()){setDsa(p=>[{...dsaForm,id:uid()},...p]);setDsaForm({...dsaForm,name:'',url:'',solution:'',notes:''});setShowDsaForm(false)}};
 const updateWork=(id,field,value)=>setWork(p=>p.map(t=>t.id===id?{...t,[field]:value}:t));
 const removeWork=id=>setWork(p=>p.filter(t=>t.id!==id));
 const removeDsa=id=>setDsa(p=>p.filter(t=>t.id!==id));
 const storyGoals=yearStory[String(storyYear)]?.goals||[];
 const storyCollage=yearStory[String(storyYear)]?.collage||[];
 const updateStory=(updater)=>setYearStory(prev=>{const current=prev[String(storyYear)]||{goals:[],collage:[]};return {...prev,[String(storyYear)]:updater(current)}});
 const readImage=(file)=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const image=new Image();image.onerror=reject;image.onload=()=>{const scale=Math.min(1,1600/Math.max(image.width,image.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);resolve({id:uid(),name:file.name,data:canvas.toDataURL('image/jpeg',0.78)})};image.src=reader.result};reader.readAsDataURL(file)});
 const addCollageImages=async(files)=>{const picked=Array.from(files||[]).filter(f=>f.type.startsWith('image/'));if(!picked.length)return;const images=await Promise.all(picked.map(readImage));updateStory(current=>({...current,collage:[...current.collage,...images]}));};
 const addYearGoal=async(e)=>{e.preventDefault();if(!goalForm.title.trim())return;let inspiration='';const file=e.currentTarget.elements.inspiration?.files?.[0];if(file)inspiration=(await readImage(file)).data;updateStory(current=>({...current,goals:[{...goalForm,id:uid(),status:'Not started',inspiration,achievementPhotos:[],createdAt:new Date().toISOString()},...current.goals]}));setGoalForm({title:'',description:'',category:'Career',priority:'Medium',targetDate:'',inspiration:''});setShowGoalForm(false)};
 const updateYearGoal=(id,patch)=>updateStory(current=>({...current,goals:current.goals.map(goal=>goal.id===id?{...goal,...patch}:goal)}));
