 const carryGoal=(goal)=>{const nextYear=String(storyYear+1);setYearStory(prev=>{const old=prev[String(storyYear)]||{goals:[],collage:[]};const next=prev[nextYear]||{goals:[],collage:[]};return {...prev,[String(storyYear)]:{...old,goals:old.goals.filter(g=>g.id!==goal.id)},[nextYear]:{...next,goals:[{...goal,id:uid(),status:'Not started',achievementPhotos:[]} ,...next.goals]}}});};
 const addExpense=e=>{e.preventDefault();const amount=Number(expenseForm.amount);if(!Number.isFinite(amount)||amount<=0)return;setExpenses(p=>[{id:uid(),date:moneyDate,category:expenseForm.category,description:expenseForm.description.trim(),amount},...p]);setExpenseForm(p=>({...p,description:'',amount:''}))};
 const deleteExpense=id=>setExpenses(p=>p.filter(x=>x.id!==id));
 const monthExpenseTotal=expenses.filter(x=>x.date?.startsWith(moneyMonth)).reduce((sum,x)=>sum+Number(x.amount||0),0);
 const monthlyCategoryTotals=Object.entries(expenses.filter(x=>x.date?.startsWith(moneyMonth)).reduce((totals,expense)=>{const category=expense.category||'Other';totals[category]=(totals[category]||0)+Number(expense.amount||0);return totals;},{})).sort((a,b)=>b[1]-a[1]);
 const selectedDayExpenses=expenses.filter(x=>x.date===moneyDate);
 const selectedDayTotal=selectedDayExpenses.reduce((sum,x)=>sum+Number(x.amount||0),0);
